import json

def aplatir(jsonl):
    lignes = []
    for texte in jsonl.splitlines():
        if not texte.strip():
            continue
        commande = json.loads(texte)
        for l in commande["lignes"]:
            lignes.append({
                "commande_id": commande["id"],
                "client": commande["client"]["nom"],
                "produit": l["produit"],
                "quantite": l["qte"],
            })
    return lignes

for l in aplatir(jsonl):
    print(l)

