from datetime import datetime
from airflow.sdk import dag, task

@dag(
    schedule="0 3 * * *",
    start_date=datetime(2026, 1, 1),
    catchup=False,
    default_args={"retries": 3},
    tags=["ventes"],
)
def pipeline_ventes():

    @task
    def extraire():
        return [{"produit": "clavier", "montant": "89.9"}]

    @task
    def transformer(lignes):
        return [{**l, "montant": float(l["montant"])} for l in lignes]

    @task
    def charger(lignes):
        print(f"{len(lignes)} lignes chargées")

    charger(transformer(extraire()))

pipeline_ventes()

exercises.statement:
Écrivez `controler(lignes, volume_veille)` qui renvoie un dictionnaire `{"bloquant": [...], "alertes": [...]}` de messages :
- **bloquant** `"doublons commande_id"` s'il existe des `commande_id` en double ;
- **bloquant** `"montant négatif"` si un `montant` est négatif ;
- **alerte** `"volume en baisse"` si le nombre de lignes est inférieur à 80 % de `volume_veille` ;
- **alerte** `"client_id manquant"` si un `client_id` vaut `None`.

