exercises.solution:
def controler(lignes, volume_veille):
    bloquant, alertes = [], []
    ids = [l["commande_id"] for l in lignes]
    if len(ids) != len(set(ids)):
        bloquant.append("doublons commande_id")
    if any(l["montant"] < 0 for l in lignes):
        bloquant.append("montant négatif")
    if len(lignes) < 0.8 * volume_veille:
        alertes.append("volume en baisse")
    if any(l["client_id"] is None for l in lignes):
        alertes.append("client_id manquant")
    return {"bloquant": bloquant, "alertes": alertes}

print(controler(lot, 10))

