def calcul_local(partition):
    totaux = {}
    for region, montant in partition:
        totaux[region] = totaux.get(region, 0) + montant
    return totaux

def combiner(resultats):
    total = {}
    for r in resultats:
        for region, montant in r.items():
            total[region] = total.get(region, 0) + montant
    return total

def ca_distribue(partitions):
    return combiner([calcul_local(p) for p in partitions])

print(ca_distribue(partitions))

