exercises.solution:
def par_fenetre(evenements, taille=5):
    totaux = {}
    vus = set()
    for e in evenements:
        if e["id"] in vus:
            continue
        vus.add(e["id"])
        debut = (e["minute"] // taille) * taille
        totaux[debut] = totaux.get(debut, 0) + e["montant"]
    return totaux

print(par_fenetre(evenements))

